# gen_fnmatch.rb: the truth table for RulesetRefPatterns against GitHub's ruleset matching.
# GitHub documents rulesets as Ruby File.fnmatch with File::FNM_PATHNAME. This writes, for each
# action kind, ref pattern and ref, the patterns a ruleset gets (written here independently of
# the Go code) and whether any of them matches the full ref. policy_test.go checks that Go emits
# the same patterns and that the policy's glob agrees with fnmatch on every row.
# Regenerate: ruby internal/hosted/policy/testdata/gen_fnmatch.rb > internal/hosted/policy/testdata/fnmatch.tsv
PREFIXES = { "merge" => ["refs/heads/"], "release" => ["refs/tags/"], "public-sync" => ["refs/heads/", "refs/tags/"] }
PATTERNS = ["*", "main", "v", "v*", "release/*", "v1.2.*", "hotfix-*", "a.b/c-*", "release/1.2"]
REFS = ["main", "Main", "v", "v1", "V1", "vx", "v1.2.3", "v1/rc", "vx/y.z-w", "release", "releasex",
        "release/1", "release/1.2", "release/1.2.3", "release/1/2", "release/a-b/c.d/e",
        "hotfix-1", "hotfix-1/x", "hotfix", "a.b/c-d", "a.b/c-d/e", "a.b/c", "a/b/c", "x"]

def emit(prefixes, pat)
  prefixes.flat_map do |pre|
    pat.end_with?("*") ? [pre + pat, pre + pat + "/**/*"] : [pre + pat]
  end
end

puts "# kind\tpattern\temitted\tref\tgithub_matches (generated by gen_fnmatch.rb with ruby #{RUBY_VERSION}; FNM_PATHNAME)"
PREFIXES.each do |kind, prefixes|
  PATTERNS.each do |pat|
    pats = emit(prefixes, pat)
    REFS.each do |ref|
      m = prefixes.any? { |pre| pats.any? { |p| File.fnmatch(p, pre + ref, File::FNM_PATHNAME) } }
      puts [kind, pat, pats.join(" "), ref, m].join("\t")
    end
  end
end
